# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps
from hourglass.errors import OutsideHoursError


def gaps_for(hours, *texts):
    worked = [parse_span(text) for text in texts]
    return find_gaps(worked, parse_span(hours))


class FindGapsTests(unittest.TestCase):
    # ---
    def test_gap_in_the_middle(self):
        result = gaps_for(
            "09:00-17:00", "09:00-12:00", "13:00-17:00"
        )
        self.assertEqual(result, [
            "gap 12:00-13:00 (60 min)"
        ])

    # ---
    def test_gaps_at_both_ends(self):
        result = gaps_for("09:00-12:30", "10:00-11:00")
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 11:00-12:30 (90 min)"
        ])

    # ---
    def test_touching_leaves_no_gap(self):
        result = gaps_for(
            "09:00-18:00",
            "09:00-13:00",
            "12:00-17:00",
            "17:00-18:00"
        )
        self.assertEqual(result, [])

    # ---
    def test_nobody_working_is_one_gap(self):
        result = gaps_for("09:00-10:00")
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)"
        ])

    # ---
    def test_unsorted_input(self):
        result = gaps_for(
            "09:00-15:00", "14:00-15:00", "09:00-10:00"
        )
        self.assertEqual(result, [
            "gap 10:00-14:00 (240 min)"
        ])

    # ---
    def test_early_start_raises(self):
        with self.assertRaises(OutsideHoursError):
            gaps_for("09:00-17:00", "08:00-10:00")

    # ---
    def test_late_end_raises(self):
        with self.assertRaises(OutsideHoursError):
            gaps_for("09:00-17:00", "16:00-18:00")
